-- 27-10-2026 (Besluit 128): module Trainingen (proef) aan voor DCG en de training van 27 okt van de trainer als eerste voorbeeld.
-- Vormen en training met scope 'eigen' op naam van de trainer (p-beheer). Tekeningen zijn een eerste versie om zelf aan te passen.
update public.rij set data = jsonb_set(data, '{modules,training}', 'true') where club_id='dcg' and soort='club' and id='club';
on conflict do nothing;
